
/* Generated by RED (red/iss.py): native reference run of fgemm10.s's c_model.
 * Prints one 32-bit word per line, lowercase hex — the exact format Spike's
 * +signature dump uses, so the two are compared line by line. */
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define RED_WORDS   200
#define RED_NVEC    100000
#define RED_NCORNER 4
#define RED_BLOCK   1024

/* ---- designer-supplied C reference model ---- */
#include <stdint.h>
#include <string.h>

/* mnemonic "fgemm10.s" -> fgemm10_s_model.
 * in[0..99]    = A, 10x10 row-major binary32: A[i][k] = in[10*i + k]
 * in[100..199] = B, 10x10 row-major binary32: B[k][j] = in[100 + 10*k + j]
 * out[10*i + j] = canon((((+0 + A[i][0]*B[0][j]) + A[i][1]*B[1][j]) + ...) + A[i][9]*B[9][j])
 * every multiply and every add separately rounded binary32 RNE; out[100..199] = 0. */
static float f32_from_bits(uint32_t u) { float f; memcpy(&f, &u, 4); return f; }
static uint32_t f32_to_bits(float f) { uint32_t u; memcpy(&u, &f, 4); return u; }

void fgemm10_s_model(const uint32_t in[200], uint32_t out[200]) {
    int i, j, k;
    for (i = 0; i < 10; i++) {
        for (j = 0; j < 10; j++) {
            float acc = f32_from_bits(0x00000000u);
            uint32_t r, is_nan, m;
            for (k = 0; k < 10; k++) {
                float a = f32_from_bits(in[10 * i + k]);
                float b = f32_from_bits(in[100 + 10 * k + j]);
                /* separate statements: product and sum rounded on their own (no contraction) */
                float p = a * b;
                acc = acc + p;
            }
            r = f32_to_bits(acc);
            is_nan = (uint32_t)((r & 0x7FFFFFFFu) > 0x7F800000u);
            m = (uint32_t)0 - is_nan;
            out[10 * i + j] = (0x7FC00000u & m) | (r & ~m);
        }
    }
    for (i = 100; i < 200; i++) out[i] = 0;
}

/* ---- end model ---- */


static uint32_t red_xs32(uint32_t *s) {
  uint32_t x = *s;
  x ^= x << 13; x ^= x >> 17; x ^= x << 5;
  return *s = x;
}

static const uint32_t RED_CORNERS[RED_NCORNER] = { 0x00000000u, 0xffffffffu, 0xaaaaaaaau, 0x55555555u };

/* Vector i: the first RED_NCORNER are uniform corner patterns, the rest are
   drawn from the PRNG. The PRNG is advanced only by the random vectors, so
   both harnesses stay in lockstep. */
static void red_fill(long i, uint32_t *seed, uint32_t *in) {
  int w;
  if (i < RED_NCORNER) {
    for (w = 0; w < RED_WORDS; w++) in[w] = RED_CORNERS[i];
  } else {
    for (w = 0; w < RED_WORDS; w++) in[w] = red_xs32(seed);
  }
}

static uint32_t red_hash(uint32_t h, const uint32_t *v, int n) {
  int w, b;
  for (w = 0; w < n; w++)
    for (b = 0; b < 4; b++) {
      h ^= (v[w] >> (8 * b)) & 0xffu;
      h *= 16777619u;
    }
  return h;
}


int main(void) {
  uint32_t in[RED_WORDS], out[RED_WORDS];
  uint32_t seed = 0xc0ffeeu, h = 2166136261u;
  long i, w, blk = 0;
  (void)blk;

  for (i = 0; i < RED_NVEC; i++) {
    red_fill(i, &seed, in);
    memset(out, 0, sizeof out);
    fgemm10_s_model(in, out);
    h = red_hash(h, out, RED_WORDS);
    if ((i + 1) % RED_BLOCK == 0 || i + 1 == RED_NVEC) {
      printf("%08x\n", h);
    }
  }
  return 0;
}
